-- =====================================================================
--  02_seed.sql  —  Data awal dari Buku "Silaturrahim Keluarga Besar
--  Bapatua H. Syafi'i - Matua Ju" (data per 31 Maret 2021)
--  Jalankan SETELAH 01_schema.sql. Aman dijalankan ulang (upsert).
--  Catatan: alamat lengkap & nomor HP sengaja TIDAK dimasukkan demi privasi;
--  domisili hanya level kota/kecamatan.
-- =====================================================================
begin;
alter table public.members disable trigger members_audit;
alter table public.marriages disable trigger marriages_audit;

on conflict (id) do update set full_name = excluded.full_name, nickname = excluded.nickname, gender = excluded.gender, birth_date = excluded.birth_date, domicile = excluded.domicile, is_deceased = excluded.is_deceased, member_type = excluded.member_type, parent_id = excluded.parent_id, co_parent_id = excluded.co_parent_id, birth_order = excluded.birth_order, hafalan_juz = excluded.hafalan_juz, bio = excluded.bio;

on conflict (member_id, spouse_id) do update set marriage_order = excluded.marriage_order, status = excluded.status;

alter table public.members enable trigger members_audit;
alter table public.marriages enable trigger marriages_audit;
commit;

-- Cek hasil:
select member_type, count(*) from public.members group by member_type order by 1;
